window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-291bd82609c5da7c"]={"versions": [{"id": "FIG-291bd82609c5da7c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur I-PDU-Übertragungssteuerung im AUTOSAR Communication Modul (COM). Das Diagramm stellt den Übertragungsmoduswechsel (Transmission Mode Selector, TMS) zwischen periodischem Senden (PERIODIC mit Zykluszeit t_c) und ereignisgesteuertem Mehrfachsenden (DIRECT/N-Times mit Wiederholungsanzahl n=3 und Sendeabstand t_d) entlang einer Zeitachse t dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitachse: Horizontale Zeitachse t.\n</li><li>Sendeereignisse (I-PDU Transmissions): Grüne vertikale Pfeile nach unten auf die Zeitachse.\n</li><li>Externe Auslöser / TMS-Umschaltungen: Rote Blitzsymbole oberhalb der Sendeereignisse.\n</li><li>Zeitintervalle und Parameter:\n<ul class=\"fig-list\"><li>t_c: Zykluszeit des periodischen Sendemodus (Periodic Transmission Period).\n</li><li>t_d: Wiederholungsintervall zwischen Übertragungen im DIRECT/N-Times-Modus.\n</li><li>dt: Übertragungsverzögerung bzw. Mindestsendeabstand (Minimum Delay Time, MDT).\n</li><li>&gt;dt: Verstreichen der Mindestsendezeit vor Wiederaufnahme der periodischen Übertragung.\n</li><li>t_p_min: Min-Delay- bzw. Mindestabstandsüberwachung am Umschaltzeitpunkt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initiale periodische Phase: I-PDUs werden zyklisch im Zeitabstand t_c übertragen.\n</li><li>TMS-Umschaltung auf DIRECT/N-Times: Ein Trigger-Ereignis (roter Blitz) initiiert den Wechsel. Nach einer Verzögerung dt startet die N-Times-Sequenz (n=3).\n</li><li>N-Times-Übertragung: Die I-PDU wird dreimal übertragen, wobei das Intervall zwischen Übertragungen durch t_d bestimmt wird. Ein erneuter Trigger-Blitz während dieser Sequenz führt zu einer weiteren N-Times-Folge.\n</li><li>TMS-Rückschaltung: Nach Ablauf der N-Times-Übertragungen und Überschreiten des Mindestabstands (&gt;dt) sowie Einhaltung von t_p_min nach einem erneuten Trigger-Ereignis wird wieder in den periodischen Übertragungsmodus mit Zykluszeit t_c zurückgekehrt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Zeitverhalten von AUTOSAR COM bei Umschaltung des Transmission Mode Selectors (TMS) gemäß Use Case 4b. Bei Konfiguration von DIRECT/N-Times mit n=3 müssen genau drei I-PDUs im Abstand t_d abgesetzt werden. Bei Re-Triggerung wird die N-Times-Sequenz neu gestartet bzw. verlängert. Die Rückkehr in den periodischen Modus (t_c) unterliegt der Mindestsendezeit (MDT / dt) und t_p_min, um Busüberlastungen zu verhindern.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-91d7af92b35cfec1", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur I-PDU-Übertragungssteuerung im AUTOSAR Communication Modul (COM). Das Diagramm stellt den Übertragungsmoduswechsel (Transmission Mode Selector, TMS) zwischen periodischem Senden (PERIODIC mit Zykluszeit t_c) und ereignisgesteuertem Mehrfachsenden (DIRECT/N-Times mit Wiederholungsanzahl n=3 und Sendeabstand t_d) entlang einer Zeitachse t dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitachse: Horizontale Zeitachse t.\n</li><li>Sendeereignisse (I-PDU Transmissions): Grüne vertikale Pfeile nach unten auf die Zeitachse.\n</li><li>Modus-Umschaltzeitpunkte / Trigger: Rote Dreiecke oberhalb gestrichelter vertikaler Linien, beschriftet mit den Modusbezeichnungen T_a (Modus A, periodisch) und T_b (Modus B, DIRECT/N-Times).\n</li><li>Zeitintervalle und Schutzzeiten:\n<ul class=\"fig-list\"><li>t_c: Zykluszeit im periodischen Übertragungsmodus T_a.\n</li><li>t_d: Wiederholungsabstand zwischen allen aufeinanderfolgenden Übertragungen der N-Times-Sequenz im Modus T_b.\n</li><li>Untere Klammern (dt, t_p): Markieren an der Zeitachse die Einhaltung bzw. Ablaufüberwachung der Minimalabstände (Minimum Delay Time) an den jeweiligen Sendezeitpunkten.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Modus T_a (Periodisch): I-PDUs werden zyklisch im Zeitabstand t_c übertragen; die Umschaltung bzw. Aktivierung wird durch die Modusmarkierung T_a eingeleitet.\n</li><li>Wechsel zu Modus T_b (DIRECT/N-Times): Der TMS wechselt zu T_b (rotes Dreieck). Nach Ablauf des Mindestabstands (Klammer dt) startet die N-Times-Übertragung mit n=3 Sendevorgängen jeweils im Abstand t_d.\n</li><li>Re-Triggerung in Modus T_b: Ein weiterer Eintritt in T_b triggert eine erneute Übertragungsfolge mit n=3 im Abstand t_d, synchronisiert an den unteren Zeitrestriktionen (dt).\n</li><li>Rückkehr zu Modus T_a: Bei Umschaltung zurück auf T_a (rotes Dreieck) wird nach Ablauf der Mindestsendezeit die periodische Übertragung im festen Zyklus t_c fortgesetzt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Zeitverhalten von AUTOSAR COM bei Umschaltung des Transmission Mode Selectors (TMS) gemäß Use Case 4b. Bei Konfiguration von DIRECT/N-Times mit n=3 müssen genau drei I-PDUs im Abstand t_d abgesetzt werden. Bei Re-Triggerung wird die N-Times-Sequenz neu gestartet bzw. verlängert. Die Rückkehr in den periodischen Modus (t_c) unterliegt der Mindestsendezeit (MDT / dt) und t_p_min, um Busüberlastungen zu verhindern.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-291bd82609c5da7c", "to": "FIG-91d7af92b35cfec1", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Ereignis- und Modus-Indikatoren</strong>: Rote Blitze zur Kennzeichnung von Sendeaufrufen/Umschaltzeitpunkten sind durch nach unten gerichtete rote Dreiecke (TMS-Umschaltung bzw. I-PDU-Callout/Sendeereignisse) ersetzt.\n</li><li><strong>TMS-Zustände</strong>: Ergänzung von Modusbezeichnungen (T_a, T_b) oberhalb der Dreiecksmarkierungen für den TMS-Zustandswechsel (T_a für periodischen Modus, T_b für DIRECT/N-Times-Modus).\n</li><li><strong>Wiederholungsabstände im N-Times-Modus (t_d)</strong>: In Fassung FIG-291bd82609c5da7c war nur der Abstand zwischen erster und zweiter Übertragung mit t_d bemaßt; in Fassung FIG-91d7af92b35cfec1 sind explizit beide Abstände zwischen den drei Übertragungen (n=3) mit t_d bemaßt.\n</li><li><strong>Mindestsendeabstand / Entprellung (t_p_min / dt)</strong>: Die Mindestabstandsüberwachung (&gt;dt, t_p_min) vor der Rückkehr in den periodischen Modus entfällt im Diagramm; stattdessen sind Sendeverzögerungen bzw. Min-Intervalle über geschweifte Klammern unterhalb der Zeitachse (dt, t_p) systematisch an den Umschalt- und Sendezeitpunkten dargestellt.\n</li></ul>"}]};
